CREATE TABLE "public"."families" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "family_name" text,
  CONSTRAINT "families_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."families"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."profiles"
  ADD COLUMN "family_id" bigint;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_family_id_fkey" FOREIGN KEY (family_id) REFERENCES public.families(id);

REVOKE ALL ON SEQUENCE "public"."families_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."families_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."families_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."families_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."families_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."families_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."families_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."families_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."families" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."families" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."families" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."families" TO "service_role";
